// The instrument origin's build manifest (ARCHITECTURE.md sections 5.9, 15.4 and 17.1: "a manifest of every engine asset
// with its SHA-256 and sizes", generated by W1-T35 under apps/instruments/src/manifest/). GATE-bundle needs one number
// from it per engine, the compressed first load, because that is the figure the loader must print (OD-6).
//
// W1-T35 owns the format, so this reader accepts the shapes the documents and the W0-S02 spike use and says exactly what
// it could not read:
//   A  { build?, engines: { <id>: { firstLoadBytes? | wireBytes?, assets: [{ path, sha256?, bytes?, wire? }] } } }
//   B  { engines: [ { engine | id | name: <id>, firstLoadBytes? | wireBytes?, assets: [...] } ] }
//   C  { assets: [ { engine: <id>, path, sha256?, bytes?, wire? } ] }
// An engine's first load is its declared figure when there is one (`firstLoadBytes`, `wireBytes`, `firstLoad`), else the sum
// of its assets' `wire` sizes (also `compressed`, `wireBytes`, `gzip`).

import { createHash } from 'node:crypto'
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { gzipSync } from 'node:zlib'

export interface EngineAsset {
  path: string
  sha256?: string
  bytes?: number
  wire?: number
}

export interface EngineEntry {
  id: string
  version?: string
  /** The compressed first load in bytes: what the loader prints. */
  firstLoadBytes: number
  /** True when the manifest states the figure itself, false when it is the sum of the assets' wire sizes. */
  declared: boolean
  assets: EngineAsset[]
}

export interface BuildManifest {
  file: string
  buildId?: string
  engines: Map<string, EngineEntry>
}

export class ManifestError extends Error {}

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)
const num = (v: unknown): number | undefined => (typeof v === 'number' && Number.isFinite(v) && v >= 0 ? v : undefined)
const str = (v: unknown): string | undefined => (typeof v === 'string' && v !== '' ? v : undefined)
const first = <T>(...vs: (T | undefined)[]): T | undefined => vs.find((v) => v !== undefined)

function readAsset(raw: unknown, where: string): EngineAsset {
  if (!isObj(raw)) throw new ManifestError(`${where}: an asset is not an object`)
  const path = str(raw['path']) ?? str(raw['file']) ?? str(raw['url'])
  if (!path) throw new ManifestError(`${where}: an asset has no path`)
  const wire = first(num(raw['wire']), num(raw['compressed']), num(raw['wireBytes']), num(raw['gzip']))
  const bytes = first(num(raw['bytes']), num(raw['size']), num(raw['rawBytes']))
  const sha256 = str(raw['sha256'])
  return { path, ...(sha256 ? { sha256 } : {}), ...(bytes !== undefined ? { bytes } : {}), ...(wire !== undefined ? { wire } : {}) }
}

function readEngine(id: string, raw: unknown, extraAssets: EngineAsset[] = []): EngineEntry {
  if (!isObj(raw)) throw new ManifestError(`engine ${id}: not an object`)
  const list = Array.isArray(raw['assets']) ? raw['assets'] : Array.isArray(raw['files']) ? raw['files'] : []
  const assets = [...list.map((a) => readAsset(a, `engine ${id}`)), ...extraAssets]
  const declaredBytes = first(num(raw['firstLoadBytes']), num(raw['firstLoad']), num(raw['wireBytes']), num(raw['wire_bytes']), num(raw['compressedBytes']))
  const summed = assets.length > 0 && assets.every((a) => a.wire !== undefined) ? assets.reduce((n, a) => n + (a.wire ?? 0), 0) : undefined
  const firstLoadBytes = declaredBytes ?? summed
  if (firstLoadBytes === undefined) {
    throw new ManifestError(`engine ${id}: no first-load figure (expected firstLoadBytes, or a wire size on every asset)`)
  }
  const version = str(raw['version'])
  return { id, ...(version ? { version } : {}), firstLoadBytes, declared: declaredBytes !== undefined, assets }
}

/** Parse a manifest document. Throws ManifestError naming what is missing. */
export function parseManifest(doc: unknown, file: string): BuildManifest {
  if (!isObj(doc)) throw new ManifestError('the manifest is not a JSON object')
  const engines = new Map<string, EngineEntry>()
  const rawEngines = doc['engines']
  if (isObj(rawEngines)) {
    for (const [id, e] of Object.entries(rawEngines)) engines.set(id, readEngine(id, e))
  } else if (Array.isArray(rawEngines)) {
    for (const e of rawEngines) {
      const id = isObj(e) ? (str(e['engine']) ?? str(e['id']) ?? str(e['name'])) : undefined
      if (!id) throw new ManifestError('an entry of engines has no engine, id or name')
      engines.set(id, readEngine(id, e))
    }
  } else if (Array.isArray(doc['assets'])) {
    const byEngine = new Map<string, EngineAsset[]>()
    for (const a of doc['assets']) {
      const id = isObj(a) ? str(a['engine']) : undefined
      if (!id) throw new ManifestError('an asset names no engine, and the manifest has no engines table')
      byEngine.set(id, [...(byEngine.get(id) ?? []), readAsset(a, `engine ${id}`)])
    }
    for (const [id, assets] of byEngine) engines.set(id, readEngine(id, {}, assets))
  } else {
    throw new ManifestError('the manifest has neither engines nor assets (see lib/manifest.ts for the shapes this gate reads)')
  }
  const buildId = str(doc['buildId']) ?? str(doc['build'])
  return { file, ...(buildId ? { buildId } : {}), engines }
}

export function readManifest(file: string): BuildManifest {
  let doc: unknown
  try {
    doc = JSON.parse(readFileSync(file, 'utf8'))
  } catch (e) {
    throw new ManifestError(`cannot read ${file}: ${e instanceof Error ? e.message : String(e)}`)
  }
  return parseManifest(doc, file)
}

const CANDIDATES = ['manifest.json', 'asset-manifest.json', 'assets.json', 'engines.json']

function* manifestCandidates(instrumentsDir: string): Generator<string> {
  const b = join(instrumentsDir, 'b')
  if (existsSync(b)) {
    // newest build first: the build's own directory is the one the host is served from
    const builds = readdirSync(b, { withFileTypes: true })
      .filter((d) => d.isDirectory())
      .map((d) => d.name)
      .sort((x, y) => statSync(join(b, y)).mtimeMs - statSync(join(b, x)).mtimeMs)
    for (const id of builds) for (const name of CANDIDATES) yield join(b, id, name)
  }
  for (const name of CANDIDATES) yield join(instrumentsDir, name)
}

/** The engine manifest of an instruments build, or null when the build has none. */
export function findManifest(instrumentsDir: string): string | null {
  for (const file of manifestCandidates(instrumentsDir)) {
    if (!existsSync(file)) continue
    try {
      const doc: unknown = JSON.parse(readFileSync(file, 'utf8'))
      if (isObj(doc) && ('engines' in doc || 'assets' in doc)) return file
    } catch {
      // not JSON: not ours
    }
  }
  return null
}

/** A text-like file is gzipped by the host (GitHub Pages sent level 5, W0-S08); a file that is already compressed is not. */
const COMPRESSIBLE = new Set(['.js', '.mjs', '.cjs', '.css', '.html', '.htm', '.json', '.svg', '.txt', '.xml', '.wasm', '.map', '.ttf', '.otf'])

export function isCompressible(path: string): boolean {
  const dot = path.lastIndexOf('.')
  return dot >= 0 && COMPRESSIBLE.has(path.slice(dot).toLowerCase())
}

const wireCache = new Map<string, number>()

/** Bytes on the wire for a file as a Pages-like host sends it: gzip level 5 for text-like files, raw otherwise. [D] */
export function wireSizeOfFile(file: string): number {
  const st = statSync(file)
  const key = `${file}:${st.size}:${st.mtimeMs}`
  const hit = wireCache.get(key)
  if (hit !== undefined) return hit
  const body = readFileSync(file)
  const n = isCompressible(file) ? gzipSync(body, { level: 5 }).length : body.length
  wireCache.set(key, n)
  return n
}

export const sha256Hex = (buf: Uint8Array): string => createHash('sha256').update(buf).digest('hex')

/** Where an asset's file is, for a path written origin-absolute (`/b/<id>/engines/x`) or relative to the manifest. */
export function assetFile(manifest: BuildManifest, instrumentsDir: string, assetPath: string): string | null {
  const bare = assetPath.replace(/^\/+/, '')
  for (const base of [instrumentsDir, dirname(manifest.file)]) {
    const f = join(base, bare)
    if (existsSync(f) && statSync(f).isFile()) return f
  }
  return null
}

export interface ManifestProblem {
  engine: string
  message: string
}

/**
 * Internal consistency of a manifest against the build it describes: every asset exists, its SHA-256 and size are the
 * file's, and the declared first load is the sum of the assets' wire sizes. The wire sizes are not recomputed: the host,
 * not this gate, chooses the compression, and the first deployment sent more bytes than the manifest's gzip level 5
 * figure for one file (W0-S02, RUN-pages-wire-check).
 */
export function checkManifestIntegrity(manifest: BuildManifest, instrumentsDir: string): ManifestProblem[] {
  const problems: ManifestProblem[] = []
  for (const e of manifest.engines.values()) {
    for (const a of e.assets) {
      const f = assetFile(manifest, instrumentsDir, a.path)
      if (!f) {
        problems.push({ engine: e.id, message: `${a.path} is listed but is not in the build` })
        continue
      }
      const body = readFileSync(f)
      if (a.bytes !== undefined && a.bytes !== body.length) problems.push({ engine: e.id, message: `${a.path}: the manifest says ${a.bytes} B, the file is ${body.length} B` })
      if (a.sha256 !== undefined && a.sha256 !== sha256Hex(body)) problems.push({ engine: e.id, message: `${a.path}: the manifest's SHA-256 is not the file's` })
    }
    if (e.declared && e.assets.length > 0 && e.assets.every((a) => a.wire !== undefined)) {
      const sum = e.assets.reduce((n, a) => n + (a.wire ?? 0), 0)
      if (sum !== e.firstLoadBytes) problems.push({ engine: e.id, message: `the first load is ${e.firstLoadBytes} B but its assets' wire sizes add to ${sum} B` })
    }
  }
  return problems
}

/** Origin-relative paths of every asset the manifest lists (a lint or a budget must not count engine bytes as host code). */
export function engineAssetPaths(manifest: BuildManifest): Set<string> {
  const out = new Set<string>()
  for (const e of manifest.engines.values()) for (const a of e.assets) out.add(a.path.replace(/^\/+/, ''))
  return out
}
